CREATE TABLE IF NOT EXISTS reservation_slot (id BIGINT NOT NULL AUTO_INCREMENT, reserved_date DATE NOT NULL, start_time TIME NOT NULL, capacity INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_reservation_slot_time (reserved_date,start_time), CONSTRAINT chk_slot_capacity CHECK (capacity > 0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reservation (id BIGINT NOT NULL AUTO_INCREMENT, slot_id BIGINT NOT NULL, guest_name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL, guest_count INT NOT NULL, note VARCHAR(1000), status VARCHAR(20) NOT NULL DEFAULT 'CONFIRMED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_reservation_active (slot_id,email,status), KEY idx_reservation_slot_status (slot_id,status), CONSTRAINT fk_reservation_slot FOREIGN KEY (slot_id) REFERENCES reservation_slot(id), CONSTRAINT chk_guest_count CHECK (guest_count > 0), CONSTRAINT chk_reservation_status CHECK (status IN ('CONFIRMED','CANCELLED'))) ENGINE=InnoDB;
